INSERT INTO forum_posts (category_id, title, body, author_name, pinned, published, published_at)
SELECT id, 'Official Trailer & the New Player Guide', 'The official OVERTHRONE SMP trailer is out! Watch it on the [home page](/#trailer): sky cities, Epic Fight combat, bosses and the RPG world.

We''ve also added a full **[Player Guide](/guide)**: installing the modpack, every important keybind (and how to fix the keys that clash), quests, coins, warps, bosses and fixes for common problems.', 'OVERTHRONE Staff', 1, 1, strftime('%Y-%m-%dT%H:%M:%SZ', 'now')
FROM forum_categories
WHERE slug = 'announcements'
  AND NOT EXISTS (SELECT 1 FROM forum_posts WHERE title = 'Official Trailer & the New Player Guide');
INSERT INTO forum_posts (category_id, title, body, author_name, pinned, published, published_at)
SELECT id, 'Update: The Hunter''s Ledger, the Arcade & the RPG World', 'A big content update for OVERTHRONE.

## The Hunter''s Ledger
- **1,012 new quests** across ten Ledgers, from Homestead to Legends of the Realm.
- Rewards are Lightman''s Currency coins, about **1,500 Netherite** for finishing everything, plus enchanted gear every 10th entry.
- The strongest modded weapons, armour and spellbooks are saved for the late Ledgers.

## The RPG World
- A protected city: blocks can''t be broken or placed, and explosions don''t damage it.
- **Questmaster Orin** opens the quest book.
- **The Arcade & Trade Hall** (/warp arcade): gacha machines for weapons, armour, enchants, runes and misc, vending machines, the exchange counter and the Community Chest.
- **The Arcanum** (/warp arcanum): enchanting and runes.

[How quests work](/guide#quests) · [Coins & the Arcade](/guide#economy)', 'OVERTHRONE Staff', 1, 1, strftime('%Y-%m-%dT%H:%M:%SZ', 'now')
FROM forum_categories
WHERE slug = 'server-updates'
  AND NOT EXISTS (SELECT 1 FROM forum_posts WHERE title = 'Update: The Hunter''s Ledger, the Arcade & the RPG World');
INSERT INTO forum_posts (category_id, title, body, author_name, pinned, published, published_at)
SELECT id, 'Changelog: October 2026', '## Gameplay
- Added the Hunter''s Ledger: 1,012 coin quests in ten chapters, alongside the 100-quest Quest Board.
- Added the RPG world: Quest Board, Arcade & Trade Hall, the Arcanum and the Community Chest.
- The RPG world is now build-protected and has a world border.
- Added Questmaster Orin, who opens the quest book.

## Website
- New [Player Guide](/guide) with verified keybinds and key conflict fixes.
- Official trailer on the home page.
- New guide posts across the forums, and the RPG world added to the Realms.', 'OVERTHRONE Staff', 1, 1, strftime('%Y-%m-%dT%H:%M:%SZ', 'now')
FROM forum_categories
WHERE slug = 'changelog'
  AND NOT EXISTS (SELECT 1 FROM forum_posts WHERE title = 'Changelog: October 2026');

INSERT OR IGNORE INTO realms (name, slug, subtitle, description, status, sort_order) VALUES
  ('THE RPG WORLD', 'rpg-world', 'Quests & Trade', 'A protected city of quests, trade and magic: Questmaster Orin and the Quest Board, the Arcade & Trade Hall and the Arcanum.', '', 15);
UPDATE site_settings SET value = 'Seven realms, each with its own role.' WHERE key = 'realms_intro' AND value = 'Six realms, each with its own role.';

UPDATE home_sections SET body = 'OVERTHRONE SMP is a modded dark-fantasy MMORPG server: Tensura: Reincarnated, Epic Fight combat, over 1,100 quests, bosses and a coin economy you grind for in game.

New here? The [Player Guide](/guide) walks you through installing the modpack, the keybinds and your first hour.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now')
WHERE title = 'Getting Started' AND instr(body, 'is currently under development.') > 0;
